// non-traumatic duplicates are replaced by their trauma entry in trauma context (shown under "Excluded by hard rules")
const TR_DUP = {tamponade:'Cardiac tamponade (traumatic)', ptx:'Tension / open pneumothorax (traumatic)'};
Object.entries(TR_DUP).forEach(([id,by])=>{ const c=KB.find(x=>x.id===id); if(!c) return; const ex0=c.ex; c.ex = S => (S.trauma ? 'trauma context – see '+by : null) || (ex0 ? ex0(S) : null); });
// a confirmed pregnancy ≥ 20 wk rules out ectopic pregnancy / miscarriage as the working diagnosis
['ectopic','miscarriage'].forEach(id=>{ const c=KB.find(x=>x.id===id); if(!c) return; const ex0=c.ex; c.ex = S => (S.pregnant && S.ga!=null && S.ga>=20 ? 'confirmed pregnancy ≥ 20 wk' : null) || (ex0 ? ex0(S) : null); });
